-- 存储过程说明：PRO_ADD_COL
CREATE PROCEDURE PRO_ADD_COL()
BEGIN
    -- 检查GOODS_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'GOODS_AMOUNT') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN GOODS_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '货物贸易金额';
END IF;

    -- 检查ADVANCE_CHARGE_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'ADVANCE_CHARGE_AMOUNT') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN ADVANCE_CHARGE_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '预付货款项下金额';
END IF;

    -- 检查ADVANCE_CONTRACT_RATE字段是否存在（比例按小数入库，需保留6位小数，否则百分位小数被截断）
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'ADVANCE_CONTRACT_RATE') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN ADVANCE_CONTRACT_RATE DECIMAL(15,6) NULL DEFAULT NULL COMMENT '预付货款项下所占合同金额比例';
ELSE
ALTER TABLE FEX_TRAN_REQ MODIFY COLUMN ADVANCE_CONTRACT_RATE DECIMAL(15,6) NULL DEFAULT NULL COMMENT '预付货款项下所占合同金额比例';
END IF;

    -- 检查RPT_GATE_DATE字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'RPT_GATE_DATE') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN RPT_GATE_DATE DECIMAL(10,0) NULL DEFAULT NULL COMMENT '预计X天后报关';
END IF;

    -- 检查RPT_GATE_ENT_ID字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'RPT_GATE_ENT_ID') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN RPT_GATE_ENT_ID VARCHAR(32) NULL DEFAULT NULL COMMENT '（已报关）报关经营单位名称';
END IF;

    -- 检查RPT_GATE_TYPE字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'RPT_GATE_TYPE') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN RPT_GATE_TYPE VARCHAR(1) NULL DEFAULT NULL COMMENT '（已报关）报关方式：人民币报关/外币报关';
END IF;

    -- 检查GENERAL_TRADE_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'GENERAL_TRADE_AMOUNT') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN GENERAL_TRADE_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '一般贸易金额';
END IF;

    -- 检查FEED_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'FEED_AMOUNT') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN FEED_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '进料加工金额';
END IF;

    -- 检查OTHER_TRADE_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'OTHER_TRADE_AMOUNT') THEN
ALTER TABLE FEX_TRAN_REQ ADD COLUMN OTHER_TRADE_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '其他贸易金额';
END IF;

    -- 检查BORDER_TRADE_AMOUNT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'BORDER_TRADE_AMOUNT') THEN
