ALTER TABLE FEX_TRAN_REQ ADD COLUMN OFFSHORE_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '离岸转手买卖金额';
END IF;

    -- 检查OTHER_AMOUNT字段是否存在
