ALTER TABLE FEX_TRAN_REQ ADD COLUMN OTHER_AMOUNT DECIMAL(15,2) NULL DEFAULT NULL COMMENT '其他金额';
END IF;

    -- 检查INVEST_AMT字段是否存在
    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'INVEST_AMT') THEN
