-- CONVERT_RATE 折本位币汇率字段精度调整：DECIMAL(8,6) -> DECIMAL(20,8)
-- 修复外汇期权交易中折本位币汇率输入过长导致提交报错的问题
DROP PROCEDURE IF EXISTS PRO_ALTER_CONVERT_RATE_DECIMAL;
DELIMITER $$


-- 存储过程说明：PRO_ALTER_CONVERT_RATE_DECIMAL
CREATE PROCEDURE PRO_ALTER_CONVERT_RATE_DECIMAL()
BEGIN
    IF EXISTS (
        SELECT 1
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'FEX_PROFIT_LOSS_MANAGE'
          AND COLUMN_NAME = 'CONVERT_RATE'
          AND NUMERIC_PRECISION = 8
    ) THEN
        ALTER TABLE `FEX_PROFIT_LOSS_MANAGE` MODIFY COLUMN `CONVERT_RATE` DECIMAL(20,8) NULL DEFAULT NULL COMMENT '折本位币汇率';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'FEX_TRAN_LIFE_CYCLE'
          AND COLUMN_NAME = 'CONVERT_RATE'
          AND NUMERIC_PRECISION = 8
    ) THEN
        ALTER TABLE `FEX_TRAN_LIFE_CYCLE` MODIFY COLUMN `CONVERT_RATE` DECIMAL(20,8) NULL DEFAULT NULL COMMENT '折本位币汇率';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'FEX_TRAN_REQ_EXT'
          AND COLUMN_NAME = 'CONVERT_RATE'
          AND NUMERIC_PRECISION = 8
    ) THEN
        ALTER TABLE `FEX_TRAN_REQ_EXT` MODIFY COLUMN `CONVERT_RATE` DECIMAL(20,8) NULL DEFAULT NULL COMMENT '折本位币汇率';
    END IF;
END$$
DELIMITER ;
CALL PRO_ALTER_CONVERT_RATE_DECIMAL();
DROP PROCEDURE IF EXISTS PRO_ALTER_CONVERT_RATE_DECIMAL;

