-- 存储过程说明：PRO_ALTER_FEX_TRAN_REQ_CODE_LEN
CREATE PROCEDURE PRO_ALTER_FEX_TRAN_REQ_CODE_LEN()
BEGIN
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'INVEST_NO' AND CHARACTER_MAXIMUM_LENGTH = 20) THEN
        ALTER TABLE `FEX_TRAN_REQ` MODIFY COLUMN `INVEST_NO` VARCHAR(200) NULL DEFAULT NULL COMMENT '投资收益 - 国际收支编码';
    END IF;
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'INVEST_APPLY_NBR' AND CHARACTER_MAXIMUM_LENGTH = 30) THEN
        ALTER TABLE `FEX_TRAN_REQ` MODIFY COLUMN `INVEST_APPLY_NBR` VARCHAR(200) NULL DEFAULT NULL COMMENT '投资收益 - 批准证书号';
    END IF;
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'OFTEN_NO' AND CHARACTER_MAXIMUM_LENGTH = 20) THEN
        ALTER TABLE `FEX_TRAN_REQ` MODIFY COLUMN `OFTEN_NO` VARCHAR(200) NULL DEFAULT NULL COMMENT '经常转移 - 国际收支编码';
    END IF;
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_REQ' AND COLUMN_NAME = 'DIRECT_INVESTMENT_CERT_NO' AND CHARACTER_MAXIMUM_LENGTH = 20) THEN
        ALTER TABLE `FEX_TRAN_REQ` MODIFY COLUMN `DIRECT_INVESTMENT_CERT_NO` VARCHAR(200) NULL DEFAULT NULL COMMENT '直接投资 - 批准证书号';
    END IF;
END$$
DELIMITER ;
CALL PRO_ALTER_FEX_TRAN_REQ_CODE_LEN();
DROP PROCEDURE IF EXISTS PRO_ALTER_FEX_TRAN_REQ_CODE_LEN;

