-- 统一外汇掉期近远端期望汇率为6位小数
DELIMITER $$
DROP PROCEDURE IF EXISTS PRO_ALTER_FEX_SWAP_WISH_RATE_SCALE$$


-- 存储过程说明：PRO_ALTER_FEX_SWAP_WISH_RATE_SCALE
CREATE PROCEDURE PRO_ALTER_FEX_SWAP_WISH_RATE_SCALE()
BEGIN
    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL'
          AND COLUMN_NAME = 'END_WISH_RATE' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL`
            MODIFY COLUMN `END_WISH_RATE` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '近端期望汇率';
    END IF;

    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL'
          AND COLUMN_NAME = 'REMOTE_END_WISH_RATE_MIN' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL`
            MODIFY COLUMN `REMOTE_END_WISH_RATE_MIN` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '远端期望汇率下限';
    END IF;

    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL'
          AND COLUMN_NAME = 'REMOTE_END_WISH_RATE_MAX' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL`
            MODIFY COLUMN `REMOTE_END_WISH_RATE_MAX` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '远端期望汇率上限';
    END IF;

    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL_TMP'
          AND COLUMN_NAME = 'END_WISH_RATE' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL_TMP`
            MODIFY COLUMN `END_WISH_RATE` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '近端期望汇率';
    END IF;

    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL_TMP'
          AND COLUMN_NAME = 'REMOTE_END_WISH_RATE_MIN' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL_TMP`
            MODIFY COLUMN `REMOTE_END_WISH_RATE_MIN` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '远端期望汇率下限';
    END IF;

    IF EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'FEX_TRAN_APP_DTL_TMP'
          AND COLUMN_NAME = 'REMOTE_END_WISH_RATE_MAX' AND (NUMERIC_PRECISION <> 14 OR NUMERIC_SCALE <> 6)
    ) THEN
        ALTER TABLE `FEX_TRAN_APP_DTL_TMP`
            MODIFY COLUMN `REMOTE_END_WISH_RATE_MAX` DECIMAL(14,6) NULL DEFAULT NULL COMMENT '远端期望汇率上限';
    END IF;
END$$
DELIMITER ;
CALL PRO_ALTER_FEX_SWAP_WISH_RATE_SCALE();
DROP PROCEDURE IF EXISTS PRO_ALTER_FEX_SWAP_WISH_RATE_SCALE;

