    'ALTER TABLE `scf_payable_voucher` ADD COLUMN `cancel_reason` varchar(500) DEFAULT NULL COMMENT ''作废原因''',
    'SELECT 1');
PREPARE scf_pv_stmt FROM @scf_pv_ddl;
